select jsonb_build_object('published',(select count(*) from public.theories where status='published'),'free',(select count(*) from public.theories where status='published' and access_tier='free'),'single_sentence',(select count(*) from public.theories where status='published' and length(coalesce(quotation->>'contextNote',summary))-length(regexp_replace(coalesce(quotation->>'contextNote',summary),'[。！？]','','g'))<2),'body_md5',(select md5(string_agg(id||summary||coalesce(quotation->>'contextNote',''),'|' order by id)) from public.theories where status='published'),'backups',(select count(*) from private.theory_reform_backups where phase='theory_depth_20261023'),'revision',(select revision from public.content_revision),'unrelated_field_changes',(select count(*) from private.theory_reform_backups b join public.theories t on t.id=b.source_id where b.phase='theory_depth_20261023' and (to_jsonb(t)-'summary'-'quotation'-'updated_at') is distinct from (b.snapshot-'summary'-'quotation'-'updated_at')),'quotation_metadata_changes',(select count(*) from private.theory_reform_backups b join public.theories t on t.id=b.source_id where b.phase='theory_depth_20261023' and (coalesce(nullif(t.quotation,'null'::jsonb),'{}'::jsonb)-'contextNote') is distinct from (coalesce(nullif(b.snapshot->'quotation','null'::jsonb),'{}'::jsonb)-'contextNote')),'paid_projection_mismatches',(select count(*) from public.theories t left join public.paid_content p on p.content_type='theory' and p.content_id=t.id where t.status='published' and t.access_tier='complete' and (p.payload->>'summary') is distinct from t.summary),'public_paid_body_leaks',(select count(*) from public.public_theories where access_tier='complete' and coalesce(summary,'')<>''),'samples',(select jsonb_agg(jsonb_build_object('id',id,'title',title,'summary',summary)) from public.theories where id in('kb_029','kb_265','kb_627'))) as verification;
